__NUXT_JSONP__("/svetovy-cas/pitcairnovy-ostrovy", (function(a,b,c,d,e,f,g,h){return {data:[{place:[{tld:".pn",name:e,area:47,population:46,slug:f,id_continent:c,information_chatgpt:"\u003Cp\u003EPitcairnovy ostrovy jsou britské zámořské území nacházející se v jižním Tichomoří, asi 2 000 km východně od Tahiti. Toto území se skládá ze čtyř sopečných ostrovů, z nichž největší je Pitcairn, kde žije většina obyvatelstva. Hlavním městem je Adamstown a úředním jazykem je angličtina.\u003C\u002Fp\u003E\n\u003Cp\u003EPitcairnovy ostrovy jsou známé díky svému jedinečnému a izolovanému umístění. Ostrovy byly objeveny britským námořníkem Robertem Pitcairnem v roce 1767 a později se zde usadili jeho potomci a další rodiny. Dnes na ostrovech žije asi 50 lidí, kteří se většinou živí rybolovem a turismem.\u003C\u002Fp\u003E\n\u003Cp\u003ETuristé na Pitcairnovy ostrovy mohou cestovat lodí ze sousedních ostrovů, nebo se sem dostat letadlem s mezizastávkou na Mangarevě v Polynésii. Ostrovy nabízejí nádherné přírodní scenérie, čisté pláže, korálové útesy a pestrou flóru a faunu. Největší atrakcí je však Pitcairnův svah, což je místo, kde se usadil Robert Pitcairn s rodinou. Zde se nachází muzeum a další historická místa, která ukazují bohatou historii ostrovů.\u003C\u002Fp\u003E\n\u003Cp\u003ENavzdory své izolaci jsou Pitcairnovy ostrovy moderním společenstvím, které má internetové připojení a moderní komunikační technologie. Turisté si mohou prohlédnout místní řemeslné výrobky, jako jsou například dřevěné sošky a suvenýry ze skořápek kokosových ořechů. Pitcairnovy ostrovy jsou zajímavým a neobvyklým místem pro návštěvu pro ty, kteří hledají klid a odpočinek na odlehlém místě v krásné přírodě.\u003C\u002Fp\u003E",currency_code:"NZD",currency_name:e,money_prices:[{name:"Taxi (cena za km)",value:a,date_update:b},{name:"Hlavní jídlo",value:a,date_update:b},{name:"Chleba",value:a,date_update:b},{name:"Mléko",value:a,date_update:b},{name:"Voda (500ml)",value:a,date_update:b},{name:"Espresso",value:a,date_update:b},{name:"Zmrzlina (jeden kopeček)",value:a,date_update:b},{name:"Pivo",value:a,date_update:b},{name:"Krabička cigaret",value:a,date_update:b},{name:"Big Mac",value:a,date_update:b},{name:"Coca Cola (500ml)",value:a,date_update:b}],phone_numbers_emergency:a,phone_prefix:"+872",coordinates:[{latitude:"-24.3408",longitude:"-128.3244"}],people_religion:a,people_nationality:a,visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup na Pitcairnovy ostrovy nestačí pouze občanský průkaz, je nutné mít platný cestovní pas.",date_update:b},{name:"Cestovní pas",value:"Pro vstup na Pitcairnovy ostrovy je nutné mít platný cestovní pas.",date_update:b},{name:"Vízum",value:"Pro občany Evropské unie není potřeba vízum pro vstup na Pitcairnovy ostrovy, ale je nutné mít platný cestovní pas.",date_update:b},{name:"Očkování",value:"Pro vstup na Pitcairnovy ostrovy není nutné očkování proti žádným nemocem.",date_update:b},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné, ale silně se doporučuje. V případě potřeby lékařské péče na ostrovech mohou být náklady velmi vysoké a pokrytí cestovním pojištěním je v takovém případě velkou výhodou.",date_update:b},{name:"Bezpečnostní situace",value:"Pitcairnovy ostrovy jsou velmi bezpečné a mírumilovné místo. Turisté se mohou těšit na přátelské přijetí ze strany místních obyvatel.",date_update:b},{name:"Další informace",value:"Při návštěvě Pitcairnových ostrovů se doporučuje respektovat místní zvyklosti a tradice, které jsou velmi důležité pro tamější obyvatele. Vzhledem k tomu, že je ostrov malý a má omezenou infrastrukturu, doporučuje se turistům si přinést všechny potřebné věci a zásoby, jako jsou například léky, potraviny a pitná voda.",date_update:b}],type_place:g,id_image_cover:d,id_image_hero:d,id_city_main:1778,affiliate:[{name:"booking",value:true}],mpz:"PN",alerts:a,zoom:[{google:7,booking:8}],ids_neighboring_countries:a,organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:181}],imagePlace:[{id:d,name:f,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-05-06T09:27:42.033044+00:00",type:g,author:"wileypics"}],placeContinent:[{id:c,slug:"australie-a-oceanie",name:"Austrálie a Oceánie",area:8560000,population:42000000,population_density:4.9,number_states:14,information_chatgpt:"\u003Cp\u003EAustrálie a Oceánie jsou kontinenty, které se nacházejí na jižní polokouli. Austrálie je největší zemí v Oceánii, zatímco Oceánie zahrnuje mnoho ostrovů v Tichomoří, včetně Nového Zélandu, Fidži, Papuy Nové Guiney, Samoa a Tongy.\u003C\u002Fp\u003E\n\u003Cp\u003EAustrálie je známá svými exotickými zvířaty, jako jsou klokani, koaly a emuové. Je také domovem mnoha překrásných pláží, kde se lze slunit, surfovat a potápět. Nejznámějšími městy jsou Sydney, Melbourne a Brisbane. Sydney je známé svým operním domem a Harbour Bridge, Melbourne je považováno za kulturní centrum a Brisbane je ideální pro milovníky adrenalinových sportů, jako je rafting a skákání padákem.\u003C\u002Fp\u003E\n\u003Cp\u003ENový Zéland, známý jako \"země dlouhé bílé obloukovité mraky\", má jedinečnou přírodu a kulturu. Nachází se zde mnoho přírodních památek, včetně hor, jezer a národních parků. Země je také domovem mnoha původních Maorů a jejich kultury. Auckland a Wellington jsou největší města na Novém Zélandu, zatímco Queenstown je oblíbená destinace pro turisty hledající adrenalinové sporty a krásnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EPapua Nová Guinea je jednou z nejvíce odlehlých a exotických destinací na světě. Země je plná původních kmenů a mnoha z nich si stále zachovávají tradiční zvyky a rituály. Turisté sem jezdí kvůli krásným plážím a překrásné přírodě. Port Moresby je hlavním městem země a láká návštěvníky svými muzei a historickými památkami.\u003C\u002Fp\u003E\n\u003Cp\u003EOceánie je také známá svými neuvěřitelnými korálovými útesy a podmořským životem. Korálové útesy Great Barrier Reef v Austrálii jsou největší na světě a lákají milovníky potápění z celého světa. Fidži a Tonga jsou další oblíbené destinace pro potápěče a snorkelisty.\u003C\u002Fp\u003E\u003Cp\u003EMezi další známé ostrovy v Oceánii patří Havajské ostrovy, které jsou součástí USA. Havajské ostrovy jsou známé svými surferskými plážemi, sopkami a krásnou přírodou. Tahiti, největší ostrov Francouzské Polynésie, láká návštěvníky svými luxusními resorty, bílými plážemi a modrými lagunami. Bora Bora, jeden z ostrovů Francouzské Polynésie, je oblíbený mezi páry hledající romantickou dovolenou.\u003C\u002Fp\u003E\n\u003Cp\u003EOceánie má také bohatou historii a kulturu původních obyvatel. Původní obyvatelé Nového Zélandu, Maorové, mají svou vlastní kulturu a jazyk. V Austrálii jsou původní obyvatelé Aboridžinci, kteří mají svůj vlastní jazyk, tradice a umění. Papua Nová Guinea má mnoho různých původních kmenů, z nichž každý má své vlastní tradice a jazyk.\u003C\u002Fp\u003E\n\u003Cp\u003ECo se týče cestování do Austrálie a Oceánie, musí cestovatelé získat víza pro vstup do země, pokud je to požadováno. Austrálie má mnoho mezinárodních letišť, zatímco v Oceánii jsou letiště menší a mohou být omezenější. Mnoho ostrovů v Tichomoří má také přísné pravidla pro dovoz zahraničních rostlin a zvířat, aby se chránila původní ekologie.\u003C\u002Fp\u003E\n\u003Cp\u003EV Austrálii a na mnoha ostrovech v Oceánii se můžete potkat s tropickým klimatem s teplými lety a mírnými zimami. V některých částech Austrálie však může být klima velmi suché a horké, zatímco na jiných místech může být velmi vlhké a deštivé.\u003C\u002Fp\u003E\n\u003Cp\u003EAustrálie a Oceánie jsou také oblíbenými destinacemi pro adrenalinové sporty, jako je potápění, surfování, skákání padákem, rafting a další. Mnoho turistů také navštěvuje Austrálii a Oceánii kvůli sportovním akcím, jako jsou tenisové turnaje v Austrálii, nebo ragbyové zápasy na Novém Zélandu.\u003C\u002Fp\u003E",coordinates:[{latitude:-25.274398,longitude:133.775136}],type_place:"continent",id_image_cover:c,id_image_hero:c,zoom:[{google:h,booking:h}],information_author:a,seo_tags:a}]}],fetch:{},mutations:[]}}(null,"05-2023",6,422,"Pitcairnovy ostrovy","pitcairnovy-ostrovy","state",3)));